package com.hfr.client.earth;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.relauncher.*;import cpw.mods.fml.relauncher.ReflectionHelper;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.*;import net.minecraft.world.WorldType;import net.minecraftforge.client.event.GuiScreenEvent;import com.hfr.world.earth.XFEarthRegistry;
/** Narrow Forge 1.7.10 create-button interception; all field names include runtime SRG aliases. */
@SideOnly(Side.CLIENT) public final class XFEarthCreateWorldHandler {
 @SubscribeEvent public void beforeCreate(GuiScreenEvent.ActionPerformedEvent.Pre e){if(!(e.gui instanceof GuiCreateWorld)||e.button.id!=0||XFEarthRegistry.get()==null)return;GuiCreateWorld g=(GuiCreateWorld)e.gui;int selected=get(g,Integer.class,"selectedIndex","field_146331_K");if(selected<0||selected>=WorldType.worldTypes.length||WorldType.worldTypes[selected]!=XFEarthRegistry.get())return;e.setCanceled(true);PendingEarthWorldCreation p=new PendingEarthWorldCreation();p.displayName=text(get(g,GuiTextField.class,"textboxWorldName","field_146333_g"));p.seedText=text(get(g,GuiTextField.class,"textboxSeed","field_146335_h"));p.folderName=get(g,String.class,"folderName","field_146336_i");p.gameMode=get(g,String.class,"gameMode","field_146342_r");p.structures=get(g,Boolean.class,"generateStructures","field_146341_s");p.commands=get(g,Boolean.class,"commandsAllowed","field_146340_t");p.bonusChest=get(g,Boolean.class,"bonusChestEnabled","field_146338_v");p.hardcore=get(g,Boolean.class,"hardCoreMode","field_146337_w");p.generatorOptions=GuiXFEarthCustomize.readOptions(g);p.packId=PendingEarthWorldCreation.packId(p.generatorOptions);Minecraft.getMinecraft().displayGuiScreen(new GuiXFEarthInstall(g,p));}
 private static String text(GuiTextField f){return f==null?"":f.getText();}
 @SuppressWarnings("unchecked") private static <T>T get(GuiCreateWorld g,Class<T> type,String mcp,String srg){try{return (T)ReflectionHelper.getPrivateValue(GuiCreateWorld.class,g,mcp,srg);}catch(Exception ex){throw new IllegalStateException("Cannot read Forge 1.7.10 GuiCreateWorld field "+mcp+"/"+srg,ex);}}
}
